/**
 * Embedded ZX Spectrum 128K ROM (32 KiB = editor + 48 BASIC).
 * Concatenation of Fuse 128-0.rom + 128-1.rom. See third_party/spectrum/README.md.
 * Generated — do not edit by hand.
 */
export const SPECTRUM128_ROM_BYTES = 32768;

export function loadSpectrum128Rom(): Uint8Array {
  const b64 = "";
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
